/* ------------------------------------------------------------------------------------------ */
/* Test-only encoder for packets the research has no vector for (depth rows, CAS, oddities).   */
/* The layout is checked against VEC_MP_L4 byte for byte in the protocol tests.                */
/* ------------------------------------------------------------------------------------------ */

export interface MpFields {
  exch: number;
  level: number;
  token: number;
  tbq: number;
  tsq: number;
  vol: number;
  ltt: number;
  lut: number;
  open: number;
  close: number;
  high: number;
  low: number;
  ltp: number;
  ltq: number;
  atp: number;
  buyCount: number;
  sellCount: number;
  pct: number;
  oi: number;
  ttv: number;
  chg: number;
  ucl: number;
  lcl: number;
  yh: number;
  yl: number;
  lot: number;
  precision: number;
  multiplier: number;
  rows: [qty: number, price: number, orders: number][];
  /** Override message_length (to test early stop). */
  length?: number;
  seq?: number;
}

/** Field values of vector (c), raw (unscaled). */
export const MP_L4_FIELDS: MpFields = {
  exch: 2, level: 4, token: 44498, tbq: 1000, tsq: 2000, vol: 50000, ltt: 1234567890, lut: 1234567891,
  open: 150000, close: 149000, high: 151000, low: 148000, ltp: 150050, ltq: 10, atp: 150025,
  buyCount: 1, sellCount: 1, pct: 123, oi: 500, ttv: 1234567.0, chg: 105, ucl: 165000, lcl: 135000,
  yh: 200000, yl: 100000, lot: 75, precision: 2, multiplier: 1, rows: [[100, 150000, 5], [101, 150100, 6]],
};

export function encodeMarketPicture(f: MpFields): Uint8Array {
  const size = 144 + 16 * f.rows.length;
  const b = new Uint8Array(size);
  const v = new DataView(b.buffer);
  v.setUint16(0, f.length ?? size, true);
  v.setUint16(2, 7208, true);
  v.setInt8(4, f.exch);
  v.setUint8(5, f.level);
  v.setUint8(7, f.seq ?? 0);
  v.setUint32(9, f.token, true);
  v.setBigInt64(13, BigInt(f.tbq), true);
  v.setBigInt64(21, BigInt(f.tsq), true);
  v.setBigInt64(29, BigInt(f.vol), true);
  v.setBigInt64(37, BigInt(f.ltt), true);
  v.setBigInt64(45, BigInt(f.lut), true);
  v.setUint32(53, f.open, true);
  v.setUint32(57, f.close, true);
  v.setUint32(61, f.high, true);
  v.setUint32(65, f.low, true);
  v.setUint32(69, f.ltp, true);
  v.setBigInt64(73, BigInt(f.ltq), true);
  v.setUint32(81, f.atp, true);
  v.setUint32(89, f.buyCount, true);
  v.setUint32(93, f.sellCount, true);
  v.setInt32(99, f.pct, true);
  v.setUint32(103, f.oi, true);
  v.setFloat64(107, f.ttv, true);
  v.setInt32(115, f.chg, true);
  v.setUint32(119, f.ucl, true);
  v.setUint32(123, f.lcl, true);
  v.setUint32(127, f.yh, true);
  v.setUint32(131, f.yl, true);
  v.setUint32(135, f.lot, true);
  v.setUint8(139, f.precision);
  v.setUint32(140, f.multiplier, true);
  f.rows.forEach(([qty, price, orders], i) => {
    const o = 144 + 16 * i;
    v.setBigInt64(o, BigInt(qty), true);
    v.setInt32(o + 8, price, true);
    v.setInt32(o + 12, orders, true);
  });
  return b;
}

/** 7207 index packet with a given exchange/token/name/value (other fields as in vector (b)). */
export function encodeIndex(p: { exch?: number; token: number; name: string; value: number; close?: number; ltt?: number }): Uint8Array {
  const b = new Uint8Array(87);
  b.set(VEC_INDEX);
  const v = new DataView(b.buffer);
  v.setInt8(4, p.exch ?? 1);
  v.setUint32(9, p.token, true);
  if (p.close !== undefined) v.setInt32(17, p.close, true);
  v.setInt32(29, p.value, true);
  if (p.ltt !== undefined) v.setBigUint64(33, BigInt(p.ltt), true);
  b.fill(0, 66, 87);
  b.set(new TextEncoder().encode(p.name).subarray(0, 21), 66);
  return b;
}

export function encodeCas(p: { exch: number; token: number; ref: number; imb: number; imbMkt: number; size?: number }): Uint8Array {
  const size = p.size ?? 48;
  const b = new Uint8Array(48);
  const v = new DataView(b.buffer);
  v.setUint16(0, size, true);
  v.setUint16(2, 104, true);
  v.setInt8(4, p.exch);
  v.setUint32(9, p.token, true);
  v.setUint32(13, p.ref, true);
  v.setBigInt64(17, BigInt(p.imb), true);
  v.setBigInt64(25, BigInt(p.imbMkt), true);
  return b.subarray(0, size);
}

/** Header-only packet with an arbitrary code/level (unknown-packet tests). */
export function encodeHeaderOnly(code: number, level = 0, size = 9, exch = 1): Uint8Array {
  const b = new Uint8Array(size);
  const v = new DataView(b.buffer);
  v.setUint16(0, size, true);
  v.setUint16(2, code, true);
  v.setInt8(4, exch);
  v.setUint8(5, level);
  return b;
}

export const concat = (...parts: Uint8Array[]): Uint8Array => {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.byteLength, 0));
  let off = 0;
  for (const p of parts) {
    out.set(p, off);
    off += p.byteLength;
  }
  return out;
};
